3	export function parseTagText(text: string): Tags {
4	  let json: unknown;
5	  try {
6	    json = JSON.parse(text);
7	  } catch {
8	    throw new Error("Tagging response was not JSON");
9	  }
10	  return TagSchema.parse(json);
11	}
